    sell_book = []  # [(price, arrival_time, id, remaining_qty)]
    order_map = {}  # id -> (side, index) or None if filled/cancelled
    arrival_time = 0

    def find_order_index(book, order_id):
        for i, (price, arrival, oid, qty) in enumerate(book):
            if oid == order_id:
                return i
        return -1

    for order in orders:
        arrival_time += 1

